using UnityEditor;
using UnityEngine;

namespace NightShift.EditorTools
{
    /// Pixel-art import settings for everything in Assets/Resources/Sprites (generated by Tools/gen_art.py).
    public class SpriteImportSettings : AssetPostprocessor
    {
        void OnPreprocessTexture()
        {
            string path = assetPath.Replace('\\', '/');
            if (!path.Contains("Resources/Sprites/")) return;

            var ti = (TextureImporter)assetImporter;
            ti.textureType = TextureImporterType.Sprite;
            ti.spriteImportMode = SpriteImportMode.Single;
            ti.spritePixelsPerUnit = 32;
            ti.filterMode = FilterMode.Point;
            ti.textureCompression = TextureImporterCompression.Uncompressed;
            ti.mipmapEnabled = false;
            ti.alphaIsTransparency = true;
            ti.wrapMode = TextureWrapMode.Clamp;

            var s = new TextureImporterSettings();
            ti.ReadTextureSettings(s);
            s.spriteAlignment = (int)SpriteAlignment.Custom;
            s.spritePivot = PivotFor(System.IO.Path.GetFileNameWithoutExtension(path));
            s.spriteMeshType = SpriteMeshType.FullRect;
            ti.SetTextureSettings(s);
        }

        static Vector2 PivotFor(string name)
        {
            if (name == "prop_camera") return new Vector2(2f / 24f, 0.5f);
            if (name.StartsWith("player_") || name.StartsWith("guard_")) return new Vector2(0.5f, 2f / 32f);
            if (name.StartsWith("prop_") && name != "prop_door_locked" && name != "prop_lamp") return new Vector2(0.5f, 0f);
            return new Vector2(0.5f, 0.5f);
        }
    }
}
